load_sip.tcl.content_utf8:
set ::quartus(sip_path) [pwd]
set assignments {}
proc set_global_assignment {libraryOpt library nameOpt name path} {
    if {$libraryOpt ne "-library" || $nameOpt ne "-name"} { error "invalid assignment" }
    lappend ::assignments [list $library $name $path]
}
source hello.sip
if {[llength $assignments]!=1} {error "expected one assignment"}
lassign [lindex $assignments 0] library name src
if {$library ne "corpus_greeting" || $name ne "MISC_FILE"} {error "wrong assignment"}
puts $src
